package com.companion.mobile;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.Bundle;import android.widget.*;import org.json.*;import java.util.*;
public class WidgetConfigActivity extends Activity {
 int id=AppWidgetManager.INVALID_APPWIDGET_ID;ArrayList<String> routes=new ArrayList<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);setResult(RESULT_CANCELED);id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(40,50,40,30);TextView title=new TextView(this);title.setText("設定 Companion Satellite Widget");title.setTextSize(21);Spinner spinner=new Spinner(this);ArrayList<String> labels=new ArrayList<>();try{JSONArray a=new JSONArray(getSharedPreferences("companion_hosts",MODE_PRIVATE).getString("hosts","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String web=o.getString("url"),lan=o.optString("lan",""),sat=MainActivity.Host.defaultSatellite(web);labels.add(o.getString("name")+" — 自動選擇區網／網際網路");routes.add(lan.isEmpty()?sat:NetworkRoute.auto(lan,sat));}}catch(Exception ignored){}if(labels.isEmpty()){labels.add("請先回 App 新增主機");routes.add("");}spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));CheckBox interaction=new CheckBox(this);interaction.setText("允許按下與旋轉");interaction.setChecked(WidgetPrefs.interactive(this,id));TextView opacityLabel=new TextView(this);SeekBar opacity=new SeekBar(this);opacity.setMin(5);opacity.setMax(100);opacity.setProgress(WidgetPrefs.opacity(this,id));opacityLabel.setText("透明度："+opacity.getProgress()+"%");opacity.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){opacityLabel.setText("透明度："+value+"%");}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}});TextView hint=new TextView(this);hint.setText("取消勾選後，Widget 只作為即時 Tally 指示燈，不會送出任何操作。");hint.setPadding(0,0,0,18);Button save=new Button(this);save.setText(WidgetPrefs.host(this,id).isEmpty()?"連線並加入 Widget":"儲存設定");box.addView(title);box.addView(spinner,new LinearLayout.LayoutParams(-1,-2));box.addView(interaction);box.addView(opacityLabel);box.addView(opacity);box.addView(hint);box.addView(save);setContentView(box);save.setOnClickListener(v->{String route=routes.get(spinner.getSelectedItemPosition());if(route.isEmpty()){Toast.makeText(this,"請先在 Companion App 新增主機",Toast.LENGTH_LONG).show();return;}AppWidgetProviderInfo info=AppWidgetManager.getInstance(this).getAppWidgetInfo(id);String n=info.provider.getClassName();String mode=n.endsWith("CompanionWidgetRotary")?"rotary1":n.endsWith("CompanionWidgetRotary4x1")?"rotary4":n.endsWith("CompanionWidgetMixed4x4")?"mixed4x4":"grid";int rows=n.endsWith("CompanionWidget1x4")||n.endsWith("4x4")?4:n.endsWith("4x3")?3:n.endsWith("4x2")||n.endsWith("3x2")||n.endsWith("2x2")?2:1;int cols=n.endsWith("CompanionWidget1x4")?1:n.endsWith("2x2")?2:n.endsWith("3x2")?3:n.endsWith("4x1")||n.endsWith("4x2")||n.endsWith("4x3")||n.endsWith("4x4")?4:1;WidgetSatelliteService.stopWidget(id);WidgetPrefs.save(this,id,route,rows,cols,mode);WidgetPrefs.setInteractive(this,id,interaction.isChecked());WidgetPrefs.setOpacity(this,id,opacity.getProgress());AppWidgetManager manager=AppWidgetManager.getInstance(this);if("rotary1".equals(mode))CompanionWidgetRotary.renderPlaceholder(this,manager,id);else if("grid".equals(mode))CompanionWidgetBase.renderPlaceholder(this,manager,id,rows,cols);else manager.updateAppWidget(id,new RemoteViews(getPackageName(),"rotary4".equals(mode)?R.layout.widget_rotary_4x1:R.layout.widget_mixed_4x4));WidgetSatelliteService.start(this,id);Intent result=new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);setResult(RESULT_OK,result);finish();});}
}
